1	//! The run's parameters as resolved: each one's value and where the value came from.
2	//!
3	//! A value reaches a run from a built-in default, a config file, or a flag, and the report used
4	//! to print some values and no sources, so a reader could not tell a box's declared `blocks`
5	//! from the built-in, or a flag typed from one forgotten. The `Config:` list prints every
6	//! parameter with its source, and marks a source that restates the default, since that value
7	//! would survive the source's removal unchanged.
8	
9	use std::path::Path;
10	
11	use crate::config::Config;
12	
13	/// Where a resolved value came from.
14	#[derive(Debug, Clone, PartialEq)]
15	pub enum Source {
16	    /// No file and no flag set it.
17	    Default,
18	    /// A config file set it, the path as loaded.
19	    File(std::path::PathBuf),
20	    /// A flag set it, as typed on the line (`--blocks`), with any qualifier the value needs.
21	    Flag(String),
22	}
23	
24	/// One run parameter: its config-key-style name, its value as the report prints it, and its
25	/// source.
26	#[derive(Debug, Clone, PartialEq)]
27	pub struct Param {
28	    /// The parameter's name, the config key where one exists (`block_sleep`).
29	    pub key: &'static str,
30	    /// The resolved value, rendered.
31	    pub value: String,
32	    /// Where the value came from.
33	    pub source: Source,
34	    /// A file or flag set the value to what the default would have given.
35	    pub same_as_default: bool,
36	}
37	
38	impl Param {
39	    /// A parameter whose value is `value` and whose default renders as `default`.
40	    pub fn new(key: &'static str, value: String, default: &str, source: Source) -> Self {
41	        let same_as_default = source != Source::Default && value == default;
42	        Param {
43	            key,
44	            value,
45	            source,
46	            same_as_default,
47	        }
48	    }
49	}
50	
51	/// Resolve one layered parameter, the flag winning, then the config file, then `default`,
52	/// returning the value and its source.
53	pub fn layered<T>(
54	    flag_value: Option<T>,
55	    flag: &str,
56	    file_value: Option<T>,
57	    key: &str,
58	    config: &Config,
59	    default: T,
60	) -> (T, Source) {
61	    if let Some(v) = flag_value {
62	        return (v, Source::Flag(flag.to_string()));
63	    }
64	    match (file_value, config.source(key)) {
65	        (Some(v), Some(path)) => (v, Source::File(path.to_path_buf())),
66	        (Some(v), None) => (v, Source::Default),
67	        (None, _) => (default, Source::Default),
68	    }
69	}
70	
71	/// [`layered`] for a parameter with no built-in value (`samples`, `record`): `None` when neither
72	/// the flag nor a file set it.
73	pub fn layered_opt<T>(
74	    flag_value: Option<T>,
75	    flag: &str,
76	    file_value: Option<T>,
77	    key: &str,
78	    config: &Config,
79	) -> (Option<T>, Source) {
80	    if let Some(v) = flag_value {
81	        return (Some(v), Source::Flag(flag.to_string()));
82	    }
83	    match (file_value, config.source(key)) {
84	        (Some(v), Some(path)) => (Some(v), Source::File(path.to_path_buf())),
85	        (v, _) => (v, Source::Default),
86	    }
87	}
88	
89	/// A path as a reader types it: the home directory as `~`.
90	pub fn display_path(path: &Path) -> String {
91	    if let Some(home) = std::env::var_os("HOME")
92	        && let Ok(rest) = path.strip_prefix(&home)
93	    {
94	        return format!("~/{}", rest.display());
95	    }
96	    path.display().to_string()
97	}
98	
99	/// A source by name alone, for a line that says who asked: `default`, the flag, or the file.
100	pub fn source_name(source: &Source) -> String {
101	    match source {
102	        Source::Default => "default".to_string(),
103	        Source::File(path) => display_path(path),
104	        Source::Flag(flag) => flag.clone(),
105	    }
106	}
107	
108	/// A source as the list prints it: `(default)`, the flag, or the file, with the restatement
109	/// marked.
110	pub fn source_cell(param: &Param) -> String {
111	    let source = match &param.source {
112	        Source::Default => return "(default)".to_string(),
113	        Source::File(path) => display_path(path),
114	        Source::Flag(flag) => flag.clone(),
115	    };
116	    if param.same_as_default {
117	        format!("({source}, same as default)")
118	    } else {
119	        format!("({source})")
120	    }
121	}
122	
123	/// Values longer than this do not widen the value column, so one long value (the `freq`
124	/// summary) does not push every other line's source to the right edge.
125	const VALUE_COLUMN_CAP: usize = 24;
126	
127	/// The `Config:` list's lines, one per parameter, name and value columns aligned, a value past
128	/// [`VALUE_COLUMN_CAP`] running over its column.
129	pub fn lines(params: &[Param]) -> Vec<String> {
130	    let mut max_value_width = 0;
131	    for p in params {
132	        if p.value.len() <= VALUE_COLUMN_CAP {
133	            max_value_width = max_value_width.max(p.value.len());
134	        }
135	    }
136	    params
137	        .iter()
138	        .map(|p| {
139	            format!(
140	                "  {:<17} {:<max_value_width$}  {}",
141	                p.key,
142	                p.value,
143	                source_cell(p)
144	            )
145	        })
146	        .collect()
147	}
