1	//! The starting config: one template, every key commented out, and the commands that write it.
2	//!
3	//! The template is `iiac-perf.example.md`, compiled in, so the file in the repo and the file an
4	//! installed binary writes cannot differ. It holds every key at its built-in default, or at a
5	//! sample value where a key has none, each one commented out, so a fresh file changes nothing
6	//! until a line is uncommented.
7	//!
8	//! - `init-config [PATH]` prints the template, or writes it to PATH, never over a file. A
9	//!   `.toml` PATH gets headings and keys without the prose, which as comments buries the keys.
10	//! - `init-config --from OLD [PATH]` brings a file up to date by writing a fresh one: the
11	//!   template with every key OLD sets uncommented at OLD's value. A key OLD lacks arrives with
12	//!   the template, and a key the loader no longer knows fails OLD's parse by name. OLD is never
13	//!   written, and its author's own prose is what the new file loses.
14	//! - Run flags on an `init-config` line set their keys in the new file, so a command line that
15	//!   worked becomes a file. Under them is what that line would have run on: the run keys the
16	//!   host's XDG and local files set, layered as the loader layers them, or `--from`'s or
17	//!   `--config NAME`'s file in their place. So the file is the run the line makes here. The
18	//!   host's `[freq]` and `[profiles]` are not copied: a run under the new file still gets them
19	//!   from the host's files, and a copied clamp is wrong on the next host.
20	//! - `update-config FILE` is the same fill written back over FILE: its own values, the line's
21	//!   over them, the old file kept as `FILE.bak` only when `--backup` asks.
22	//! - `setup-freq` creates a missing XDG file from the same template, the live `[freq]` filled in.
23	//!
24	//! The template's one rule makes this mechanical: inside a `toml` fence a `#` with no space
25	//! after it is a commented-out key or table header, `#blocks = 100`, and one with a space is a
26	//! comment. A table has a fence to itself after every top-level key.
27	
28	use std::io::Write;
29	use std::path::Path;
30	
31	use crate::config;
32	
33	/// The template, in the markdown carrier.
34	pub const TEMPLATE: &str = include_str!("../iiac-perf.example.md");
35	
36	/// A template fence line as a key line: `#blocks = 100` is `blocks = 100`. A `#` with a space
37	/// after it is a comment, never a key, which is how a reader tells the two apart too.
38	fn uncommented(line: &str) -> Option<&str> {
39	    let body = line.strip_prefix('#')?;
40	    if body.starts_with(' ') || body.is_empty() {
41	        None
42	    } else {
43	        Some(body)
44	    }
45	}
46	
47	/// The table a header line opens: `[freq]` is `freq`.
48	fn table_name(line: &str) -> Option<&str> {
49	    line.strip_prefix('[')?.strip_suffix(']')
50	}
51	
52	/// The key a top-level key line sets: `blocks = 100` is `blocks`.
53	fn key_name(line: &str) -> Option<&str> {
54	    let (key, _) = line.split_once('=')?;
55	    Some(key.trim())
56	}
57	
58	/// The template with `old`'s values set and, when given, `freq_section` in place of the
59	/// `[freq]` sample: the live state's lines, the header first, as `setup-freq` has them. An error
60	/// when one of `old`'s tables will not write back as TOML, so a file never silently lacks it.
61	pub fn render(
62	    old: Option<&toml::Table>,
63	    freq_section: Option<&[String]>,
64	) -> Result<String, String> {
65	    let mut out = String::new();
66	    let mut in_fence = false;
67	    // Inside a table's fence whose lines were replaced: the template's samples are dropped.
68	    let mut dropping = false;
69	    // Inside a table's fence at all: its lines are the table's entries, not top-level keys.
70	    let mut in_table = false;
71	    for line in TEMPLATE.lines() {
72	        if !in_fence {
73	            in_fence = line.starts_with("```toml");
74	            out.push_str(line);
75	            out.push('\n');
76	            continue;
77	        }
78	        if line.starts_with("```") {
79	            (in_fence, dropping, in_table) = (false, false, false);
80	            out.push_str(line);
81	            out.push('\n');
82	            continue;
83	        }
84	        if dropping {
85	            continue;
86	        }
87	        let replaced = match uncommented(line) {
88	            Some(body) if table_name(body).is_some() => {
89	                in_table = true;
90	                table_lines(body, old, freq_section)?
91	            }
92	            Some(body) if !in_table => key_line(body, old),
93	            _ => None,
94	        };
95	        match replaced {
96	            Some(text) => {
97	                dropping = in_table;
98	                out.push_str(&text);
99	            }
100	            None => {
101	                out.push_str(line);
102	                out.push('\n');
103	            }
104	        }
105	    }
106	    Ok(out)
107	}
108	
109	/// The lines that replace a table's commented sample, `None` when nothing sets that table.
110	fn table_lines(
111	    header: &str,
112	    old: Option<&toml::Table>,
113	    freq_section: Option<&[String]>,
114	) -> Result<Option<String>, String> {
115	    let Some(name) = table_name(header) else {
116	        return Ok(None);
117	    };
118	    if name == "freq"
119	        && let Some(section) = freq_section
120	    {
121	        let mut text = String::new();
122	        for line in section {
123	            text.push_str(line);
124	            text.push('\n');
125	        }
126	        return Ok(Some(text));
127	    }
128	    let Some(value) = old.and_then(|t| t.get(name)) else {
129	        return Ok(None);
130	    };
131	    let mut table = toml::Table::new();
132	    table.insert(name.to_string(), value.clone());
133	    match toml::to_string(&table) {
134	        Ok(text) => Ok(Some(text)),
135	        Err(e) => Err(format!("[{name}] will not write back as TOML: {e}")),
136	    }
137	}
138	
139	/// The line that replaces a commented top-level key, when `old` sets it.
140	fn key_line(body: &str, old: Option<&toml::Table>) -> Option<String> {
141	    let key = key_name(body)?;
142	    let value = old?.get(key)?;
143	    Some(format!("{key} = {value}\n"))
144	}
145	
146	/// What heads the TOML carrier in place of the prose it leaves out.
147	const TOML_HEAD: &str = "\
148	# iiac-perf config: every key, commented out at its default, or at a sample where it has none.
149	# Uncomment a line to set it. `iiac-perf init-config` prints this file with the prose that
150	# explains each key, and docs/config.md is the reference.
151	";
152	
153	/// A markdown config as plain TOML: the fences' lines as they are, each section's heading as a
154	/// ruled comment, and the prose left out. As comments the prose and the commented keys both
155	/// begin `# `, and a set key is lost among them, where markdown's fences keep the two apart.
156	fn to_toml(md: &str) -> String {
157	    let mut out = TOML_HEAD.to_string();
158	    let mut in_fence = false;
159	    for line in md.lines() {
160	        if line.starts_with("```") {
161	            // A section's fences run together: the blank lines are the headings'.
162	            in_fence = !in_fence && line.starts_with("```toml");
163	        } else if in_fence {
164	            out.push_str(line);
165	            out.push('\n');
166	        } else if let Some(heading) = line.strip_prefix("## ") {
167	            out.push_str(&format!("\n# ---- {heading} ----\n\n"));
168	        }
169	    }
170	    out
171	}
172	
