174	pub enum Start<'a> {
175	    /// The host's files, as a plain run layers them.
176	    Host,
177	    /// `--from OLD`: this file.
178	    From(&'a Path),
179	    /// `--config NAME`: the file the search finds.
180	    Named(&'a Path),
181	}
