33	/// The template, in the markdown carrier.
34	pub const TEMPLATE: &str = include_str!("../iiac-perf.example.md");
35	
36	/// A template fence line as a key line: `#blocks = 100` is `blocks = 100`. A `#` with a space
37	/// after it is a comment, never a key, which is how a reader tells the two apart too.
38	fn uncommented(line: &str) -> Option<&str> {
39	    let body = line.strip_prefix('#')?;
40	    if body.starts_with(' ') || body.is_empty() {
41	        None
42	    } else {
43	        Some(body)
44	    }
45	}
46	
47	/// The table a header line opens: `[freq]` is `freq`.
48	fn table_name(line: &str) -> Option<&str> {
49	    line.strip_prefix('[')?.strip_suffix(']')
50	}
51	
52	/// The key a top-level key line sets: `blocks = 100` is `blocks`.
53	fn key_name(line: &str) -> Option<&str> {
54	    let (key, _) = line.split_once('=')?;
55	    Some(key.trim())
56	}
57	
58	/// The template with `old`'s values set and, when given, `freq_section` in place of the
59	/// `[freq]` sample: the live state's lines, the header first, as `setup-freq` has them. An error
60	/// when one of `old`'s tables will not write back as TOML, so a file never silently lacks it.
61	pub fn render(
62	    old: Option<&toml::Table>,
63	    freq_section: Option<&[String]>,
64	) -> Result<String, String> {
65	    let mut out = String::new();
66	    let mut in_fence = false;
67	    // Inside a table's fence whose lines were replaced: the template's samples are dropped.
68	    let mut dropping = false;
69	    // Inside a table's fence at all: its lines are the table's entries, not top-level keys.
70	    let mut in_table = false;
71	    for line in TEMPLATE.lines() {
72	        if !in_fence {
73	            in_fence = line.starts_with("```toml");
74	            out.push_str(line);
75	            out.push('\n');
76	            continue;
77	        }
78	        if line.starts_with("```") {
79	            (in_fence, dropping, in_table) = (false, false, false);
80	            out.push_str(line);
81	            out.push('\n');
82	            continue;
83	        }
84	        if dropping {
85	            continue;
86	        }
87	        let replaced = match uncommented(line) {
88	            Some(body) if table_name(body).is_some() => {
89	                in_table = true;
90	                table_lines(body, old, freq_section)?
91	            }
92	            Some(body) if !in_table => key_line(body, old),
93	            _ => None,
94	        };
95	        match replaced {
96	            Some(text) => {
97	                dropping = in_table;
98	                out.push_str(&text);
99	            }
100	            None => {
101	                out.push_str(line);
102	                out.push('\n');
103	            }
104	        }
105	    }
106	    Ok(out)
107	}
108	
109	/// The lines that replace a table's commented sample, `None` when nothing sets that table.
110	fn table_lines(
111	    header: &str,
112	    old: Option<&toml::Table>,
113	    freq_section: Option<&[String]>,
114	) -> Result<Option<String>, String> {
115	    let Some(name) = table_name(header) else {
116	        return Ok(None);
117	    };
118	    if name == "freq"
119	        && let Some(section) = freq_section
120	    {
121	        let mut text = String::new();
122	        for line in section {
123	            text.push_str(line);
124	            text.push('\n');
125	        }
126	        return Ok(Some(text));
127	    }
128	    let Some(value) = old.and_then(|t| t.get(name)) else {
129	        return Ok(None);
130	    };
131	    let mut table = toml::Table::new();
132	    table.insert(name.to_string(), value.clone());
133	    match toml::to_string(&table) {
134	        Ok(text) => Ok(Some(text)),
135	        Err(e) => Err(format!("[{name}] will not write back as TOML: {e}")),
136	    }
137	}
