139	/// The line that replaces a commented top-level key, when `old` sets it.
140	fn key_line(body: &str, old: Option<&toml::Table>) -> Option<String> {
141	    let key = key_name(body)?;
142	    let value = old?.get(key)?;
143	    Some(format!("{key} = {value}\n"))
